  // Technique detail info
  'techniques.box.detail': 'Navy SEALs \u099A\u09BE\u09AA \u09AA\u09B0\u09BF\u099A\u09BE\u09B2\u09A8\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7\u0964 \u09B8\u09AE\u09BE\u09A8 \u09B6\u09CD\u09AC\u09BE\u09B8, \u09A7\u09B0\u09C7 \u09B0\u09BE\u0996\u09BE, \u09A8\u09BF\u09B6\u09CD\u09AC\u09BE\u09B8 \u0993 \u09A7\u09B0\u09C7 \u09B0\u09BE\u0996\u09BE\u09B0 \u09AA\u09B0\u09CD\u09AF\u09BE\u09AF\u09BC \u098F\u0995\u099F\u09BF \u09B6\u09BE\u09A8\u09CD\u09A4 \u099B\u09A8\u09CD\u09A6 \u09A4\u09C8\u09B0\u09BF \u0995\u09B0\u09C7 \u09AF\u09BE \u0995\u09B0\u09CD\u099F\u09BF\u09B8\u09B2 \u0995\u09AE\u09BE\u09AF\u09BC \u0993 \u09AB\u09CB\u0995\u09BE\u09B8 \u09AC\u09BE\u09DC\u09BE\u09AF\u09BC\u0964',
