  'techniques.triangle.detail': '\u09A8\u09A4\u09C1\u09A8\u09A6\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u0995\u099F\u09BF \u09B8\u09B9\u099C 3-\u09AA\u09B0\u09CD\u09AF\u09BE\u09AF\u09BC \u09AA\u09CD\u09AF\u09BE\u099F\u09BE\u09B0\u09CD\u09A8\u0964 \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A7\u09B0\u09C7 \u09B0\u09BE\u0996\u09BE \u099B\u09BE\u09DC\u09BE\u0987 \u09B8\u09CD\u09A8\u09BE\u09AF\u09BC\u09C1\u09A4\u09A8\u09CD\u09A4\u09CD\u09B0\u0995\u09C7 \u09B8\u09AE\u09A8\u09CD\u09AC\u09AF\u09BC \u0995\u09B0\u09C7, \u09AF\u09BE \u09B8\u09AC\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09B8\u09B9\u099C \u0993 \u09B8\u09C1\u09B2\u09AD\u0964',
