  // Motivational quotes
  'summary.quote1': '"\u09B6\u09CD\u09AC\u09BE\u09B8 \u09B8\u09C7\u0987 \u09B8\u09C7\u09A4\u09C1 \u09AF\u09BE \u099C\u09C0\u09AC\u09A8\u0995\u09C7 \u099A\u09C7\u09A4\u09A8\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u09C1\u0995\u09CD\u09A4 \u0995\u09B0\u09C7\u0964" \u2014 \u09A5\u09BF\u099A \u09A8\u09BE\u099F \u09B9\u09BE\u09A8\u09CD\u09B9',
