  'summary.quote10': '"\u0986\u09AA\u09A8\u09BE\u09B0 \u09B6\u09CD\u09AC\u09BE\u09B8 \u0986\u09A4\u09CD\u09AE-\u09A8\u09BF\u09AF\u09BC\u09A8\u09CD\u09A4\u09CD\u09B0\u09A3\u09C7\u09B0 \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AC\u09DC \u09B8\u09B0\u099E\u09CD\u099C\u09BE\u09AE\u0964"',
