  'summary.quote12': '"\u09B9\u09BE\u09B8\u09C1\u09A8, \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A8\u09BF\u09A8, \u0993 \u09A7\u09C0\u09B0\u09C7 \u099A\u09B2\u09C1\u09A8\u0964" \u2014 \u09A5\u09BF\u099A \u09A8\u09BE\u099F \u09B9\u09BE\u09A8\u09CD\u09B9',
  'summary.quote13': '"\u099C\u09C0\u09AC\u09A8 \u0995\u09A4\u0997\u09C1\u09B2\u09BF \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A8\u09BF\u09B2\u09BE\u09AE \u09A4\u09BE \u09A6\u09BF\u09AF\u09BC\u09C7 \u09AE\u09BE\u09AA\u09BE \u09B9\u09AF\u09BC \u09A8\u09BE, \u09AC\u09B0\u0982 \u09AF\u09C7 \u09AE\u09C1\u09B9\u09C2\u09B0\u09CD\u09A4\u0997\u09C1\u09B2\u09BF \u0986\u09AE\u09BE\u09A6\u09C7\u09B0 \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A5\u09BE\u09AE\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u09AF\u09BC \u09A4\u09BE \u09A6\u09BF\u09AF\u09BC\u09C7\u0964"',
  'summary.quote14': '"\u09B6\u09CD\u09AC\u09BE\u09B8\u0987 \u099C\u09C0\u09AC\u09A8, \u0993 \u09AD\u09BE\u09B2\u09CB\u09AD\u09BE\u09AC\u09C7 \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A8\u09BF\u09B2\u09C7 \u09AA\u09C3\u09A5\u09BF\u09AC\u09C0\u09A4\u09C7 \u09A6\u09C0\u09B0\u09CD\u0998 \u099C\u09C0\u09AC\u09A8 \u09AA\u09BE\u09AC\u09C7\u09A8\u0964" \u2014 \u09B8\u0982\u09B8\u09CD\u0995\u09C3\u09A4 \u09AA\u09CD\u09B0\u09AC\u09BE\u09A6',
  'summary.quote15': '"\u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AC\u09C1\u09A6\u09CD\u09A7\u09BF\u09AE\u09BE\u09A8 \u098F\u0995-\u09B6\u09AC\u09CD\u09A6\u09C7\u09B0 \u09AC\u09BE\u0995\u09CD\u09AF? \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A8\u09BF\u09A8\u0964" \u2014 \u099F\u09C7\u09B0\u09BF \u0997\u09BF\u09B2\u09C7\u09AE\u09C7\u099F\u09B8',
  'summary.quote16': '"\u0997\u09AD\u09C0\u09B0\u09AD\u09BE\u09AC\u09C7 \u09B6\u09CD\u09AC\u09BE\u09B8 \u09A8\u09BF\u09A8, \u09AF\u09A4\u0995\u09CD\u09B7\u09A3 \u09A8\u09BE \u09AE\u09BF\u09B7\u09CD\u099F\u09BF \u09AC\u09BE\u09A4\u09BE\u09B8 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AB\u09C1\u09B8\u09AB\u09C1\u09B8\u09C7\u09B0 \u09AD\u09AF\u09BC\u09C7\u09B0 \u09A6\u09B9\u09A8 \u09A8\u09BF\u09AD\u09BF\u09AF\u09BC\u09C7 \u09A6\u09C7\u09AF\u09BC\u0964" \u2014 \u09AD\u09BF\u0995\u09CD\u099F\u09CB\u09B0\u09BF\u09AF\u09BC\u09BE \u098F\u09B0\u09BF\u0995\u09B8\u09A8',
  'summary.quote17': '"\u0986\u09AA\u09A8\u09BE\u09B0 \u09B6\u09CD\u09AC\u09BE\u09B8\u09C7 \u09A6\u0995\u09CD\u09B7\u09A4\u09BE \u0985\u09B0\u09CD\u099C\u09A8 \u0995\u09B0\u09C1\u09A8, \u0986\u09A4\u09CD\u09AE\u09BE\u0995\u09C7 \u09AA\u09B0\u09AE\u09BE\u09A8\u09A8\u09CD\u09A6\u09C7 \u09A5\u09BE\u0995\u09A4\u09C7 \u09A6\u09BF\u09A8\u0964" \u2014 \u099F\u09BF. \u0995\u09C3\u09B7\u09CD\u09A3\u09AE\u09BE\u099A\u09BE\u09B0\u09CD\u09AF',
  'summary.quote18': '"\u0989\u09A6\u09CD\u09A6\u09C0\u09AA\u09A8\u09BE \u0993 \u09AA\u09CD\u09B0\u09A4\u09BF\u0995\u09CD\u09B0\u09BF\u09AF\u09BC\u09BE\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u098F\u0995\u099F\u09BF \u09B8\u09CD\u09A5\u09BE\u09A8 \u0986\u099B\u09C7\u0964 \u09B8\u09C7\u0987 \u09B8\u09CD\u09A5\u09BE\u09A8\u09C7\u0987 \u0986\u09AE\u09BE\u09A6\u09C7\u09B0 \u09B8\u09CD\u09AC\u09BE\u09A7\u09C0\u09A8\u09A4\u09BE\u0964" \u2014 \u09AD\u09BF\u0995\u09CD\u099F\u09B0 \u09AB\u09CD\u09B0\u09CD\u09AF\u09BE\u0999\u09CD\u0995\u09B2',
  'summary.quote19': '"\u09AF\u0996\u09A8 \u09B6\u09CD\u09AC\u09BE\u09B8 \u0985\u09B8\u09CD\u09A5\u09BF\u09B0 \u09B9\u09AF\u09BC \u09AE\u09A8\u0993 \u0985\u09B8\u09CD\u09A5\u09BF\u09B0 \u09B9\u09AF\u09BC\u0964 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09B6\u09CD\u09AC\u09BE\u09B8 \u09B6\u09BE\u09A8\u09CD\u09A4 \u09B9\u09B2\u09C7 \u09AE\u09A8\u0993 \u09B8\u09CD\u09A5\u09BF\u09B0 \u09B9\u09AF\u09BC\u0964" \u2014 \u09B9\u09A0 \u09AF\u09CB\u0997 \u09AA\u09CD\u09B0\u09A6\u09C0\u09AA\u09BF\u0995\u09BE',
  'summary.quote20': '"\u09AC\u09C7\u0981\u099A\u09C7 \u09A5\u09BE\u0995\u09BE\u09B0 \u098F\u0995\u09AE\u09BE\u09A4\u09CD\u09B0 \u0989\u09AA\u09BE\u09AF\u09BC \u09B9\u09B2 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BF \u09AE\u09C1\u09B9\u09C2\u09B0\u09CD\u09A4\u0995\u09C7 \u098F\u0995\u099F\u09BF \u0985\u09A8\u09A8\u09CD\u09AF \u0985\u09B2\u09CC\u0995\u09BF\u0995 \u0998\u099F\u09A8\u09BE \u09B9\u09BF\u09B8\u09C7\u09AC\u09C7 \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09BE\u0964" \u2014 \u09A4\u09BE\u09B0\u09BE \u09AC\u09CD\u09B0\u09CD\u09AF\u09BE\u0995',
  'summary.quote21': '"\u09B6\u09CD\u09AC\u09BE\u09B8 \u09AA\u09CD\u09B0\u0995\u09C3\u09A4\u09BF\u09B0 \u09B8\u09C7\u09B0\u09BE \u0989\u09AA\u09B9\u09BE\u09B0\u0964 \u098F\u0987 \u0985\u09A6\u09CD\u09AD\u09C1\u09A4 \u0989\u09AA\u09B9\u09BE\u09B0\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0995\u09C3\u09A4\u099C\u09CD\u099E \u09A5\u09BE\u0995\u09C1\u09A8\u0964" \u2014 \u0985\u09AE\u09BF\u09A4 \u09B0\u09C7',
  'summary.quote22': '"\u0997\u09A4\u09BF \u0993 \u09AC\u09BF\u09B6\u09C3\u0999\u09CD\u0996\u09B2\u09BE\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AD\u09C7\u09A4\u09B0\u09C7 \u09B6\u09BE\u09A8\u09CD\u09A4\u09BF \u09AC\u099C\u09BE\u09AF\u09BC \u09B0\u09BE\u0996\u09C1\u09A8\u0964" \u2014 \u09A6\u09C0\u09AA\u0995 \u099A\u09CB\u09AA\u09DC\u09BE',
