  'summary.quote24': '"\u09AA\u09CD\u09B0\u09BE\u09AF\u09BC \u09B8\u09AC\u0995\u09BF\u099B\u09C1 \u0986\u09AC\u09BE\u09B0 \u0995\u09BE\u099C \u0995\u09B0\u09AC\u09C7 \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u098F\u099F\u09BF \u0995\u09BF\u099B\u09C1\u0995\u09CD\u09B7\u09A3\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09C7 \u09A6\u09C7\u09A8, \u0986\u09AA\u09A8\u09BF\u0993\u0964" \u2014 \u0985\u09CD\u09AF\u09BE\u09A8 \u09B2\u09CD\u09AF\u09BE\u09AE\u099F',
